(()=>{"use strict";const memory=new Map;let account="",state=null,options=null,timer=null,dismiss=null;const key=id=>`loverwatch:lovys-evolutions:v1:${id}`;const escape=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));function read(id){if(memory.has(id))return memory.get(id);let value;try{value=JSON.parse(localStorage.getItem(key(id)))}catch{}const data={levels:{},pending:[],generation:String(value?.generation||"")};if(value&&typeof value.levels==="object"&&value.levels){for(const[id,level]of Object.entries(value.levels)){if(/^[a-z0-9_-]+$/i.test(id)&&Number.isFinite(level))data.levels[id]=Math.max(1,Math.min(50,level))}if(Array.isArray(value.pending))data.pending=value.pending.filter(x=>x&&typeof x.creatureId==="string"&&[25,50].includes(x.level)).slice(0,20)}memory.set(id,data);return data}function save(){if(!account||!state)return;try{localStorage.setItem(key(account),JSON.stringify(state))}catch{}}function reset(){clearTimeout(timer);timer=null;dismiss?.();dismiss=null;account="";state=null;options=null}function pump(){clearTimeout(timer);timer=null;if(dismiss||!state?.pending.length)return;if(document.hidden||options.isBlocked?.()){timer=setTimeout(pump,400);return}const item=state.pending[0],owner=account;const oldImage=options.imageFor(item.creatureId,item.level===50?2:0);const newImage=options.imageFor(item.creatureId,item.level===50?3:2);if(!oldImage||!newImage){state.pending.shift();save();pump();return}dismiss=show(item,oldImage,newImage,()=>{if(owner!==account)return;dismiss?.();dismiss=null;state.pending.shift();save();pump()})}function observe(input){if(!input.accountId){reset();return}const id=String(input.accountId);if(id!==account){reset();account=id;state=read(id)}options=input;const generation=String(input.progressResetAt||"");if(state.generation!==generation){dismiss?.();dismiss=null;state.levels={};state.pending=[];state.generation=generation}for(const lovy of input.lovys||[]){const creatureId=String(lovy.creatureId||"");const level=Number(lovy.level);if(!/^[a-z0-9_-]+$/i.test(creatureId)||!input.imageFor(creatureId,0)||!Number.isFinite(level))continue;const previous=state.levels[creatureId];if(previous!==undefined)for(const threshold of[25,50]){if(previous<threshold&&level>=threshold&&!state.pending.some(x=>x.creatureId===creatureId&&x.level===threshold)){state.pending.push({creatureId:creatureId,name:String(lovy.name||"Ton Lovys"),level:threshold})}}state.levels[creatureId]=Math.max(previous||1,Math.min(50,level))}save();clearTimeout(timer);timer=setTimeout(pump,0)}function show(item,oldImage,newImage,finish){const previousFocus=document.activeElement;const overlay=document.createElement("div");overlay.className="lovys-evolution-cinematic";overlay.setAttribute("role","dialog");overlay.setAttribute("aria-modal","true");overlay.setAttribute("aria-labelledby","lovysEvolutionTitle");overlay.setAttribute("aria-describedby","lovysEvolutionDescription");const bonus=item.level===50?30:15;overlay.innerHTML=`<section class="lovys-evolution-panel"><div class="lovys-evolution-kicker">✦ ÉVOLUTION · NIVEAU ${item.level}</div><h2 id="lovysEvolutionTitle">${escape(item.name)} évolue !</h2><p id="lovysEvolutionDescription" role="status" aria-live="polite">Une nouvelle énergie s’éveille…</p><div class="lovys-evolution-stage" aria-hidden="true"><div class="lovys-evolution-orbit"></div><div class="lovys-evolution-sparkles">${Array.from({length:12},(_,i)=>`<i style="--angle:${i*30}deg;--delay:${i*.09}s"></i>`).join("")}</div><img class="lovys-evolution-before" src="${escape(oldImage)}" alt=""><img class="lovys-evolution-after" src="${escape(newImage)}" alt=""></div><div class="lovys-evolution-progress" aria-hidden="true"><span></span></div><div class="lovys-evolution-rewards" hidden><strong>${item.level===50?"Évolution maximale":"Forme évoluée"}</strong><div class="lovys-evolution-stats">${["PV","ATQ","DEF","VIT"].map(stat=>`<div><span>${stat}</span><b>+${bonus} %</b></div>`).join("")}</div><p>Bonus total d’évolution${item.level===50?" : remplace les +15 % précédents":""}.</p><small>Ton rang, tes étoiles et ton talent sont conservés.</small></div><button class="lovys-evolution-next" type="button">Passer l’animation</button></section>`;let revealed=false,closed=false,revealTimer,startTimer;const button=overlay.querySelector("button");function reveal(){if(closed||revealed)return;revealed=true;clearTimeout(revealTimer);clearTimeout(startTimer);overlay.classList.remove("is-running");overlay.classList.add("is-revealed");overlay.querySelector("h2").textContent=`${item.name} a évolué !`;overlay.querySelector('[role="status"]').textContent="Une nouvelle forme, plus de puissance !";overlay.querySelector(".lovys-evolution-rewards").hidden=false;button.textContent="Continuer"}const onKey=event=>{if(event.key==="Escape"){event.preventDefault();event.stopImmediatePropagation();revealed?finish():reveal()}else if(event.key==="Tab"){event.preventDefault();event.stopImmediatePropagation();button.focus()}};button.addEventListener("click",()=>revealed?finish():reveal());document.body.appendChild(overlay);document.body.classList.add("lovys-evolution-playing");document.addEventListener("keydown",onKey,true);button.focus({preventScroll:true});const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches||document.body.classList.contains("game-reduce-motion");if(reduced)reveal();else{let started=false;const start=()=>{if(started||closed||revealed)return;started=true;clearTimeout(startTimer);overlay.classList.add("is-running");revealTimer=setTimeout(reveal,3600)};const pictures=[...overlay.querySelectorAll("img")];Promise.all(pictures.map(img=>img.decode?img.decode().catch(()=>{}):Promise.resolve())).then(start);startTimer=setTimeout(start,1200)}return()=>{closed=true;clearTimeout(revealTimer);clearTimeout(startTimer);document.removeEventListener("keydown",onKey,true);overlay.remove();document.body.classList.remove("lovys-evolution-playing");if(previousFocus?.isConnected&&previousFocus.getClientRects().length)previousFocus.focus({preventScroll:true})}}window.LovysEvolutionCelebration={observe:observe,reset:reset,isActive:()=>Boolean(dismiss)}})();